#include "generation_formats.hpp"
#include "presentation.hpp"
#include <iostream>
using namespace fa;
namespace {int checks=0;void check(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}const Json& named(const Result& r,std::string_view name){for(const auto& item:r.generation)if(item["name"].is_string()&&item["name"].get_ref<const std::string&>()==name)return item["value"];throw std::runtime_error("Missing generation value: "+std::string(name));} }
int wmain(int argc,wchar_t** argv){try{
 check(argc==2,"Expected fixtures");fs::path root=argv[1];Options options;options.useParser=options.useC2pa=false;std::atomic_bool cancel=false;
 auto invoke=analyze(root/L"invokeai.png",options,cancel);check(named(invoke,"Prompt")=="fixture lighthouse"&&named(invoke,"Seed")==0,"InvokeAI named JSON recovers prompt and zero seed without guessing");check(named(invoke,"Model name claimed")=="fixture model"&&named(invoke,"Model hash")=="fixture-model-hash","Documented model properties interpreted separately from the full record");check(named(invoke,"InvokeAI metadata JSON")["future_property"]["kept"]==true,"Unknown future properties preserved in full JSON");check(named(invoke,"InvokeAI workflow JSON")["nodes"].is_array()&&named(invoke,"InvokeAI graph JSON")["nodes"].is_object(),"Workflow and executed graph shapes preserved independently");check(named(invoke,"LoRAs and weights")[0]["weight"]==0.6,"Nested model and LoRA records retained");
 auto focus=analyze(root/L"fooocus.png",options,cancel);check(named(focus,"Prompt")=="fixture forest"&&named(focus,"Seed")==0&&named(focus,"Model")=="fixture checkpoint","Marker-qualified Fooocus JSON interpreted");check(named(focus,"Resolution")=="(1024, 768)"&&named(focus,"LoRAs and weights/hashes")[0][1]==0.7,"Fooocus tuple-like strings retained as data without eval");
 auto nai=analyze(root/L"novelai.png",options,cancel);check(named(nai,"Prompt")=="fixture red boat"&&named(nai,"Negative prompt")=="fixture blur"&&named(nai,"Seed")==0,"NovelAI visible JSON requires an explicit metadata marker");check(named(nai,"NovelAI visible metadata JSON")["signed_hash"]=="UNVERIFIED-FIXTURE","Vendor signature value preserved without claiming verification");check(named(nai,"Structured prompt record")["caption"]["base_caption"]=="fixture red boat","Structured newer prompt values remain available");
 auto ordinary=analyze(root/L"ordinary-json-comment.png",options,cancel);check(ordinary.generation.empty(),"An ordinary JSON comment cannot impersonate NovelAI without a marker");
 auto broken=analyze(root/L"broken-invokeai.png",options,cancel);check(broken.generation.empty()&&!broken.errors.empty(),"Malformed named metadata reports an error and retains original fields");
 Result diagnostic;diagnostic.fields.push_back({"Analysis diagnostics","invokeai_metadata","ExifTool","",R"({"seed":5,"positive_prompt":"false"})",nullptr,{},{}});parseStructuredGeneration(diagnostic);check(diagnostic.generation.empty(),"Scanner diagnostics are excluded from generator recognition");
 Result huge;huge.fields.push_back({"PNG text","invokeai_metadata","Native","",std::string(1024*1024+1,'x'),nullptr,{},{}});parseStructuredGeneration(huge);check(huge.generation.empty()&&!huge.errors.empty(),"Oversized structured generation metadata is bounded and reported");
 Result deep;deep.fields.push_back({"PNG text","invokeai_metadata","Native","",std::string(200,'[')+std::string(200,']'),nullptr,{},{}});parseStructuredGeneration(deep);check(deep.generation.empty()&&!deep.errors.empty(),"Excessively nested generator JSON refused");
 Result plain;plain.fields.push_back({"PNG text","prompt","Native","","An ordinary textual prompt",nullptr,{},{}});parseGeneration(plain);check(plain.generation.empty()&&plain.errors.empty(),"An ordinary prompt field is retained without a spurious malformed-ComfyUI claim");
 Result malformedNode;malformedNode.fields.push_back({"PNG text","prompt","Native","",R"({"1":{"class_type":123,"inputs":{}}})",nullptr,{},{}});parseGeneration(malformedNode);check(malformedNode.generation.empty(),"Invalid ComfyUI node types are not promoted into a recognized generation record");
 for(auto file:{L"invokeai.png",L"fooocus.png",L"novelai.png"}){auto hash=sha256File(root/file,cancel);auto result=analyze(root/file,options,cancel);check(hash==sha256File(root/file,cancel),"Generator inspection never changes source bytes");check(result.origin["assessment"]=="Generation settings recovered","Additional conventions feed the origin summary");auto findings=simpleFindings(result);bool found=false;for(const auto& finding:findings)if(finding.title=="Prompt")found=true;check(found,"Readable settings are surfaced in Simple");}
 std::cout<<"PASS: "<<checks<<" generation format assertions\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" generation assertions: "<<e.what()<<"\n";return 1;}}
